```python
class Node:
    def __init__(self, val):
        self.val = val
        self.next = None
def remove_duplicates(head):
    if not head:
        return None

    prev = head
    curr = head.next
    seen = set([head.val])

    while curr:
        if curr.val in seen:
            prev.next = curr.next
        else:
            seen.add(curr.val)
            prev = curr
        curr = curr.next

    return head
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
def filter_primes(head):
    if not head:
        return None

    curr = head
    primes = []

    while curr:
        if is_prime(curr.val):
            primes.append(curr.val)
        curr = curr.next

    primes.sort(reverse=True)

    new_head = Node(primes[0])
    curr = new_head

    for i in range(1, len(primes)):
        curr.next = Node(primes[i])
        curr = curr.next

    return new_head
```
The `remove_duplicates` function takes a singly linked list represented by its head node and removes any duplicate values in the list. It uses a set to keep track of values that it has seen before and removes any nodes whose values have already been seen.
The `filter_primes` function takes the resulting linked list from `remove_duplicates` and filters out any non-prime values. It then sorts the prime values in descending order and creates a new linked list with those values.
Note that this implementation assumes that the input linked list contains only integer values. If the input can contain non-integer values, additional checks would need to be added to ensure that only integers are checked for primality.

