public class ReverseArray {
    public static int[] reverseArray(int[] nums) {
        int[] reversedArray = new int[nums.length];
        for (int i = 0; i < nums.length; i++) {
            reversedArray[i] = nums[nums.length - i - 1];
        }
        return reversedArray;
