```
func findWordsInPuzzle(_ puzzle: [[Character]], _ wordsToFind: [String]) -> [(String, [(Int, Int)], String)] {
    var results: [(String, [(Int, Int)], String)] = []

    let numRows = puzzle.count
    let numCols = puzzle[0].count

    // Check horizontally
    for row in 0..<numRows {
        for col in 0..<(numCols - max(wordsToFind.map({ $0.count }))) {
            let substring = String(puzzle[row][col..<(col + wordsToFind[0].count)])
            for word in wordsToFind {
                if substring == word {
                    results.append((word, (row, col)..<(row, col + word.count), "horizontal"))
                }
            }
        }
    }

    // Check vertically
    for row in 0..<(numRows - max(wordsToFind.map({ $0.count }))) {
        for col in 0..<numCols {
            var substring = ""
            for i in 0..<wordsToFind[0].count {
                substring.append(puzzle[row + i][col])
            }
            for word in wordsToFind {
                if substring == word {
                    results.append((word, (row, col)..<(row + word.count, col), "vertical"))
                }
            }
        }
    }

    // Check diagonally (top-left to bottom-right)
    for row in 0..<(numRows - max(wordsToFind.map({ $0.count }))) {
        for col in 0..<(numCols - max(wordsToFind.map({ $0.count }))) {
            var substring = ""
            for i in 0..<wordsToFind[0].count {
                substring.append(puzzle[row + i][col + i])
            }
            for word in wordsToFind {
                if substring == word {
                    results.append((word, (row, col)..<(row + word.count, col + word.count), "diagonal"))
                }
            }
        }
    }

    // Check diagonally (bottom-left to top-right)
    for row in (max(wordsToFind.map({ $0.count }))..<numRows {
        for col in 0..<(numCols - max(wordsToFind.map({ $0.count }))) {
            var substring = ""
            for i in 0..<wordsToFind[0].count {
                substring.append(puzzle[row - i][col + i])
            }
            for word in wordsToFind {
                if substring == word {
                    results.append((word, (row, col)..<(row - word.count, col + word.count), "diagonal"))
                }
            }
        }
    }

    return results
}
// Example usage
let puzzle: [[Character]] = [["C","S","S","L","O","C","A","L","H","O","S","T"],
                             ["E","H","T","M","L","I","F","R","A","M","E","B"],
                             ["A","C","K","E","N","D","R","J","A","X","J","A"],
                             ["V","A","S","C","R","I","P","T","C","O","D","E"],
                             ["W","G","E","A","P","I","P","H","P","M","Y","S"],
                             ["Q","L","E","R","B","U","N","D","S","R","V","R"],
                             ["I","T","N","E","S","S","I","O","N","S","T","S"]]
let wordsToFind = ["CSS", "HTML", "IFRAME", "BACKEND", "JAVASCRIPT", "API", "PHP", "MYSQL", "SERVER", "CLIENT", "AJAX", "SESSIONS", "DOCUMENTS"]
let results = findWordsInPuzzle(puzzle, wordsToFind)
for result in results {
    print("\(result.0) found at \(result.1) going \(result.2)")
}
```
This program works by first checking for matches horizontally, then vertically, then diagonally (top-left to bottom-right), and finally diagonally (bottom-left to top-right). For each match, it adds a tuple to the `results` array containing the word, the range of coordinates where the word was found, and the direction it was going. Finally, it returns the `results` array.

