using System.Collections.Generic;
class Program
{
    static void Main(string[] args)
    {
        // Define the lists of nouns, verbs, and adjectives
        List<string> nouns = new List<string> { "dog", "cat", "house", "car", "book", "phone" };
        List<string> verbs = new List<string> { "runs", "jumps", "eats", "reads", "drives", "talks" };
        List<string> adjectives = new List<string> { "big", "small", "fast", "slow", "old", "new" };
        // Generate 10 random sentences
        for (int i = 0; i < 10; i++)
        {
            // Randomly select one word from each category
            string noun = nouns[new Random().Next(nouns.Count)];
            string verb = verbs[new Random().Next(verbs.Count)];
            string adjective = adjectives[new Random().Next(adjectives.Count)];
            // Concatenate the words to form a sentence
            string sentence = $"{noun} {verb} {adjective}.";
            // Print the sentence
            Console.WriteLine(sentence);
        }
        // Wait for user input before closing the console window
        Console.ReadLine();
    }
}
```
This program defines three lists of words (nouns, verbs, and adjectives), and then generates 10 random sentences by randomly selecting one word from each category and concatenating them to form a sentence. The program uses the `Random` class to generate random numbers for selecting words from the lists. Finally, the program prints each sentence to the console.
