Sure! Here's an algorithm in C++ that shuffles the deck of cards:
```
#include <iostream>
#include <cstdlib>
#include <ctime>
using namespace std;
void shuffleDeck(string *suits, string *cardNumbers, int deckSize)
{
    srand(time(0)); // seed the random number generator

    for(int i = deckSize - 1; i > 0; i--)
    {
        int j = rand() % (i + 1); // generate a random index between 0 and i

        // swap the cards at index i and j
        string tempSuit = suits[i];
        string tempCardNumber = cardNumbers[i];
        suits[i] = suits[j];
        cardNumbers[i] = cardNumbers[j];
        suits[j] = tempSuit;
        cardNumbers[j] = tempCardNumber;
    }
}
int main()
{
    const int deckSize = 52;
    string suits[4] = {"Clubs", "Diamonds", "Hearts", "Spades"};
    string cardNumbers[13] = {"Ace", "2", "3", "4", "5", "6", "7", "8", "9", "10", "Jack", "Queen", "King"};

    shuffleDeck(suits, cardNumbers, deckSize);

    // print the shuffled deck
    for(int i = 0; i < deckSize; i++)
    {
        cout << suits[i/13] << " " << cardNumbers[i%13] << endl;
    }

    return 0;
}
```
Explanation:
- We use the `srand` function to seed the random number generator with the current time, so that each time we run the program, we get a different sequence of random numbers.
- We loop through the deck of cards backwards, starting from the last card and going up to the second card.
- For each card, we generate a random index `j` between 0 and `i` (inclusive), where `i` is the current index of the card we're shuffling.
- We swap the cards at index `i` and `j`.
- After shuffling, we print the shuffled deck by looping through the array of suits and card numbers, and using the formula `i/13` to get the index of the suit, and `i%13` to get the index of the card number.
This algorithm shuffles the deck of cards randomly and ensures that each card in the deck has an equal chance of being in any position in the shuffled deck.

